/* Value of cp in a range table (0 if absent). */
static inline uint8_t uni_lookup(const UniRange *t, int n, uint32_t cp) {
    int lo = 0, hi = n - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (cp < t[mid].lo) hi = mid - 1;
        else if (cp > t[mid].hi) lo = mid + 1;
        else return t[mid].v;
    }
    return 0;
}
#define UNI_N(t) ((int)(sizeof t / sizeof *t))

